WITH flagged_elements AS ( SELECT ARRAY_TO_STRING( [ CASE WHEN PERSON_FULL_NAME IS NOT NULL OR (PERSON_FIRST_NAME IS NOT NULL AND PERSON_LAST_NAME IS NOT NULL) THEN 'Name' END, CASE WHEN PERSON_ID IS NOT NULL THEN 'ID' END, CASE WHEN PERSON_EMAIL IS NOT NULL THEN 'Email' END, CASE WHEN PERSON_PHONE_NUM IS NOT NULL THEN 'Phone Number' END, CASE WHEN PHONE_ID IS NOT NULL THEN 'Phone ID' END, CASE WHEN PERSON_DATE_OF_BIRTH IS NOT NULL THEN 'Date of Birth' END, CASE WHEN PERSON_TAX_ID IS NOT NULL THEN 'Tax ID' END, CASE WHEN PERSON_ADDRESS_FULL IS NOT NULL OR (PERSON_ADDRESS_STREET IS NOT NULL AND PERSON_ADDRESS_LINE2 IS NOT NULL) THEN 'Address' END, CASE WHEN FULL_CC_NUM IS NOT NULL THEN 'Credit Card Number' END, CASE WHEN CC_CVV IS NOT NULL THEN 'CC CVV' END, CASE WHEN CC_EXPIRATION IS NOT NULL THEN 'CC Expiration' END, CASE WHEN BANK_ACCT_NUM IS NOT NULL THEN 'Bank Account Number' END, CASE WHEN BANK_ROUTING_NUM IS NOT NULL THEN 'Bank Routing Number' END, CASE WHEN DRIVERS_LICENSE IS NOT NULL THEN 'Drivers License' END, CASE WHEN PASSPORT IS NOT NULL THEN 'Passport' END, CASE WHEN MILITARY_ID IS NOT NULL THEN 'Military ID' END, CASE WHEN GOVERNMENT_ID IS NOT NULL THEN 'Government ID' END, CASE WHEN GEOLOCATION IS NOT NULL THEN 'Geolocation' END, CASE WHEN PATIENT_ID_TYPE IS NOT NULL THEN 'Patient ID Type' END, CASE WHEN PATIENT_ID IS NOT NULL THEN 'Patient ID' END, CASE WHEN IMEI_NUM IS NOT NULL THEN 'IMEI' END, CASE WHEN IMSI_NUM IS NOT NULL THEN 'IMSI' END, CASE WHEN E_SIM_SIM_EZ IS NOT NULL THEN 'eSIM/SIM EZ' END, CASE WHEN BOOL_EMPLOYEE_COMPENSATION THEN 'Employee Compensation' END, CASE WHEN BOOL_BIOMETRIC_DATA THEN 'Biometric Data' END, CASE WHEN BOOL_DIGITAL_SIGNATURE THEN 'Digital Signature' END, CASE WHEN BOOL_END_USER_CONTRACT THEN 'End User Contract' END, CASE WHEN BOOL_PATIENT_HISTORY THEN 'Patient History' END ], ' + ' ) AS PRESENT_ELEMENTS, FARM_FINGERPRINT( TO_JSON_STRING( STRUCT( CASE WHEN PERSON_FULL_NAME IS NOT NULL OR (PERSON_FIRST_NAME IS NOT NULL AND PERSON_LAST_NAME IS NOT NULL) THEN COALESCE(PERSON_FULL_NAME, CONCAT(PERSON_FIRST_NAME, ' ', PERSON_LAST_NAME)) END AS MATCHING_NAME, CASE WHEN PERSON_FULL_NAME IS NOT NULL OR (PERSON_FIRST_NAME IS NOT NULL AND PERSON_LAST_NAME IS NOT NULL) THEN PERSON_MIDDLE_NAME END AS PERSON_MIDDLE_NAME, CASE WHEN PERSON_FULL_NAME IS NOT NULL OR (PERSON_FIRST_NAME IS NOT NULL AND PERSON_LAST_NAME IS NOT NULL) THEN PERSON_SUFFIX END AS PERSON_SUFFIX, PERSON_ID, PERSON_EMAIL, PERSON_PHONE_NUM, PHONE_ID, PERSON_DATE_OF_BIRTH, PERSON_TAX_ID, CASE WHEN PERSON_ADDRESS_FULL IS NOT NULL OR (PERSON_ADDRESS_STREET IS NOT NULL AND PERSON_ADDRESS_LINE2 IS NOT NULL) THEN COALESCE(PERSON_ADDRESS_FULL, CONCAT(PERSON_ADDRESS_STREET, ' ', PERSON_ADDRESS_LINE2)) END AS MATCHING_ADDRESS, CASE WHEN PERSON_ADDRESS_FULL IS NOT NULL OR (PERSON_ADDRESS_STREET IS NOT NULL AND PERSON_ADDRESS_LINE2 IS NOT NULL) THEN PERSON_ADDRESS_CITY END AS PERSON_ADDRESS_CITY, CASE WHEN PERSON_ADDRESS_FULL IS NOT NULL OR (PERSON_ADDRESS_STREET IS NOT NULL AND PERSON_ADDRESS_LINE2 IS NOT NULL) THEN PERSON_ADDRESS_STATE END AS PERSON_ADDRESS_STATE, CASE WHEN PERSON_ADDRESS_FULL IS NOT NULL OR (PERSON_ADDRESS_STREET IS NOT NULL AND PERSON_ADDRESS_LINE2 IS NOT NULL) THEN PERSON_ADDRESS_ZIP END AS PERSON_ADDRESS_ZIP, CASE WHEN PERSON_ADDRESS_FULL IS NOT NULL OR (PERSON_ADDRESS_STREET IS NOT NULL AND PERSON_ADDRESS_LINE2 IS NOT NULL) THEN PERSON_ADDRESS_COUNTRY END AS PERSON_ADDRESS_COUNTRY, FULL_CC_NUM, CC_CVV, CC_EXPIRATION, DRIVERS_LICENSE, PASSPORT, MILITARY_ID, GOVERNMENT_ID, BANK_ACCT_NUM, BANK_ROUTING_NUM, GEOLOCATION, PATIENT_ID_TYPE, PATIENT_ID, IMEI_NUM, IMSI_NUM, E_SIM_SIM_EZ, BOOL_EMPLOYEE_COMPENSATION, BOOL_BIOMETRIC_DATA, BOOL_DIGITAL_SIGNATURE, BOOL_END_USER_CONTRACT, BOOL_PATIENT_HISTORY ) ) ) AS RAW_VALUES_HASH FROM `cio-mosaic-analytics-pr-853ae3.bronze.stg_dataload_person_raw` ) SELECT IF(PRESENT_ELEMENTS = '', 'Potential Exclusions', PRESENT_ELEMENTS) AS UNIQUE_COMBINATION, COUNT(DISTINCT RAW_VALUES_HASH) AS UNIQUE_VALUE_COMBINATIONS_COUNT, COUNT(1) AS TOTAL_RECORD_COUNT FROM flagged_elements GROUP BY PRESENT_ELEMENTS ORDER BY UNIQUE_VALUE_COMBINATIONS_COUNT DESC
